/// The fields of a [`Keywords`], to write
#[derive(Clone, Debug)]
pub struct KeywordsFields<'a> {
    pub class: u8,
    pub default: u8,
    pub r#in: u8,
    pub r#match: u8,
    pub self_: u8,
    pub r#type: &'a str,
}

impl KeywordsFields<'_> {
    /// The alignment that a parent pads a [`Keywords`] to: the largest alignment of its
    /// arrays and nested tables, or 1
    pub const ALIGNMENT: Alignment = Alignment::One;

    /// Adds a [`Keywords`] to its parent's sizer, after the field or vector that holds it
    pub fn size(&self, sizer: &mut TableSizer) {
        let parent = sizer.start_table(6);
        sizer.add_u8();
        sizer.add_u8();
        sizer.add_u8();
        sizer.add_u8();
        sizer.add_u8();
        sizer.add_str(self.r#type);
        sizer.end_table(parent);
    }

    /// Writes a [`Keywords`] where its parent's writer is, after the field or vector that holds it
    pub fn write(&self, writer: &mut TableWriter) {
        let parent = writer.start_table(6);
        writer.set_u8(0, self.class);
        writer.set_u8(1, self.default);
        writer.set_u8(2, self.r#in);
        writer.set_u8(3, self.r#match);
        writer.set_u8(4, self.self_);
        writer.set_str(5, self.r#type);
        writer.end_table(parent);
    }
}

/// A message that nests the table of keywords, so that it's written
#[derive(Clone, Copy, Debug)]
pub struct Reserved<'a> {
    bytes: &'a [u8],
}

impl<'a> Reserved<'a> {
    const LAYOUT: TableLayout = TableLayout::DEFAULT;

    /// Reads a [`Reserved`] from `bytes`
    pub const fn new(bytes: &'a [u8]) -> Self {
        Self { bytes }
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn keywords(&self) -> Result<Keywords<'a>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(0)?;
        Ok(Keywords::new(self.bytes, position))
    }
}

/// The fields of a [`Reserved`], to write
#[derive(Clone, Debug)]
pub struct ReservedFields<'a> {
    pub keywords: KeywordsFields<'a>,
}

impl ReservedFields<'_> {
    /// Writes a [`Reserved`] with every field
    ///
    /// # Errors
    ///
    /// Returns a [`BuildError`] if it's longer than its offset type, `uint32`, addresses.
    pub fn serialize(&self) -> Result<Vec<u8>, BuildError> {
        let mut sizer = TableSizer::new(1, Reserved::LAYOUT)?;
        sizer.add_table(KeywordsFields::ALIGNMENT);
        self.keywords.size(&mut sizer);

        let mut writer = sizer.writer()?;
        writer.set_table(0, KeywordsFields::ALIGNMENT);
        self.keywords.write(&mut writer);

        writer.into_bytes()
    }
}

/// Structs as fields, in place like scalars, and in arrays, which are aligned
/// to their structs' largest scalar
#[derive(Clone, Copy, Debug)]
pub struct Structs<'a> {
    bytes: &'a [u8],
}

impl<'a> Structs<'a> {
    const LAYOUT: TableLayout = TableLayout::DEFAULT;

    /// Reads a [`Structs`] from `bytes`
    pub const fn new(bytes: &'a [u8]) -> Self {
        Self { bytes }
    }

    /// A struct of every scalar type
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn packed(&self) -> Result<Packed, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(0)?;
        let bytes = reader.get_struct(position, Packed::SIZE)?;

        Packed::read(bytes)
    }

    /// An array of structs of 7 bytes, aligned to 4
    ///
    /// A view of the structs, which reads each [`Documented`] when it's asked for
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field or its structs lie outside the bytes.
    pub fn documented(&self) -> Result<DocumentedArray<'a>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(1)?;
        let bytes = reader.get_struct_array(position, Documented::SIZE)?;
        let (structs, _) = bytes.as_chunks::<{ Documented::SIZE }>();

        Ok(DocumentedArray { structs })
    }

    /// A struct of structs
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn segment(&self) -> Result<Segment, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(2)?;
        let bytes = reader.get_struct(position, Segment::SIZE)?;

        Segment::read(bytes)
    }

    /// A view of the structs, which reads each [`Segment`] when it's asked for
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field or its structs lie outside the bytes.
    pub fn segments(&self) -> Result<SegmentArray<'a>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(3)?;
        let bytes = reader.get_struct_array(position, Segment::SIZE)?;
        let (structs, _) = bytes.as_chunks::<{ Segment::SIZE }>();

        Ok(SegmentArray { structs })
    }

    /// A table nested in the message, which holds structs too
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn path(&self) -> Result<Path<'a>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(4)?;
        Ok(Path::new(self.bytes, position))
    }
}

/// The fields of a [`Structs`], to write
#[derive(Clone, Debug)]
pub struct StructsFields<'a, T = Documented, U = Segment> {
    /// A struct of every scalar type
    pub packed: Packed,
    /// An array of structs of 7 bytes, aligned to 4
    ///
    /// [`Documented`]s, or items of any type `T` whose reference converts into a [`Documented`]
    pub documented: &'a [T],
    /// A struct of structs
    pub segment: Segment,
    /// [`Segment`]s, or items of any type `U` whose reference converts into a [`Segment`]
    pub segments: &'a [U],
    /// A table nested in the message, which holds structs too
    pub path: PathFields<'a>,
}

impl<'a, T, U> StructsFields<'a, T, U>
where
    &'a T: Into<Documented>,
    &'a U: Into<Segment>,
{
    /// Writes a [`Structs`] with every field
    ///
    /// # Errors
    ///
    /// Returns a [`BuildError`] if it's longer than its offset type, `uint32`, addresses.
    pub fn serialize(&self) -> Result<Vec<u8>, BuildError> {
        let mut sizer = TableSizer::new(5, Structs::LAYOUT)?;
        sizer.add_struct(Packed::SIZE);
        sizer.add_struct_array(
            self.documented.len(),
            Documented::SIZE,
            Documented::ALIGNMENT,
        );
        sizer.add_struct(Segment::SIZE);
        sizer.add_struct_array(self.segments.len(), Segment::SIZE, Segment::ALIGNMENT);
        sizer.add_table(PathFields::ALIGNMENT);
        self.path.size(&mut sizer);

        let mut writer = sizer.writer()?;
        writer.set_struct(0, &self.packed.to_bytes());
        writer.set_structs(
            1,
            self.documented,
            |item| Documented::to_bytes(item.into()),
            Documented::ALIGNMENT,
        );
        writer.set_struct(2, &self.segment.to_bytes());
        writer.set_structs(
            3,
            self.segments,
            |item| Segment::to_bytes(item.into()),
            Segment::ALIGNMENT,
        );
        writer.set_table(4, PathFields::ALIGNMENT);
        self.path.write(&mut writer);

        writer.into_bytes()
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Path<'a> {
    bytes: &'a [u8],
    position: usize,
}

impl<'a> Path<'a> {
    /// Reads the table at `position` in `bytes`, as its parent's getter finds it
    const fn new(bytes: &'a [u8], position: usize) -> Self {
        Self { bytes, position }
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn start(&self) -> Result<Point, DecodeError> {
        let reader = TableReader::new(self.bytes, TableLayout::DEFAULT);
        let position = reader.field_offset(self.position, 0)?;
        let bytes = reader.get_struct(position, Point::SIZE)?;

        Point::read(bytes)
    }

    /// A view of the structs, which reads each [`Point`] when it's asked for
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field or its structs lie outside the bytes.
    pub fn points(&self) -> Result<PointArray<'a>, DecodeError> {
        let reader = TableReader::new(self.bytes, TableLayout::DEFAULT);
        let position = reader.field_offset(self.position, 1)?;
        let bytes = reader.get_struct_array(position, Point::SIZE)?;
        let (structs, _) = bytes.as_chunks::<{ Point::SIZE }>();

        Ok(PointArray { structs })
    }
}

/// The fields of a [`Path`], to write
#[derive(Clone, Debug)]
pub struct PathFields<'a, T = Point> {
    pub start: Point,
    /// [`Point`]s, or items of any type `T` whose reference converts into a [`Point`]
    pub points: &'a [T],
}

impl PathFields<'_> {
    /// The alignment that a parent pads a [`Path`] to: the largest alignment of its
    /// arrays and nested tables, or 1
    pub const ALIGNMENT: Alignment = Alignment::Four;
}

impl<'a, T> PathFields<'a, T>
where
    &'a T: Into<Point>,
{
    /// Adds a [`Path`] to its parent's sizer, after the field or vector that holds it
    pub fn size(&self, sizer: &mut TableSizer) {
        let parent = sizer.start_table(2);
        sizer.add_struct(Point::SIZE);
        sizer.add_struct_array(self.points.len(), Point::SIZE, Point::ALIGNMENT);
        sizer.end_table(parent);
    }

    /// Writes a [`Path`] where its parent's writer is, after the field or vector that holds it
    pub fn write(&self, writer: &mut TableWriter) {
        let parent = writer.start_table(2);
        writer.set_struct(0, &self.start.to_bytes());
        writer.set_structs(
            1,
            self.points,
            |item| Point::to_bytes(item.into()),
            Point::ALIGNMENT,
        );
        writer.end_table(parent);
    }
}

/// Two points, whose scalars lie in the segment's place
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Segment {
    pub start: Point,
    pub end: Point,
}

impl Segment {
    /// The byte length of a [`Segment`]
    pub const SIZE: usize = 16;

    /// The alignment of an array of a [`Segment`]: its largest scalar's size
    pub const ALIGNMENT: Alignment = Alignment::Four;

    /// Reads a [`Segment`] from the start of `bytes`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if `bytes` are shorter than [`Self::SIZE`].
    pub fn read(bytes: &[u8]) -> Result<Self, DecodeError> {
        match bytes.first_chunk() {
            Some(bytes) => Ok(Self::from_bytes(bytes)),
            None => Err(DecodeError::OutOfRange {
                position: 0,
                byte_length: 16,
                available: bytes.len(),
            }),
        }
    }

    /// Reads a [`Segment`] from its bytes, such as those of an array of them
    #[must_use]
    pub fn from_bytes(bytes: &[u8; 16]) -> Self {
        Self {
            start: Point {
                x: f32::from_le_bytes(bytes[0..4].try_into().unwrap_or_default()),
                y: f32::from_le_bytes(bytes[4..8].try_into().unwrap_or_default()),
            },
            end: Point {
                x: f32::from_le_bytes(bytes[8..12].try_into().unwrap_or_default()),
                y: f32::from_le_bytes(bytes[12..16].try_into().unwrap_or_default()),
            },
        }
    }

    #[must_use]
    pub fn to_bytes(self) -> [u8; 16] {
        let mut bytes = [0; Self::SIZE];
        bytes[0..8].copy_from_slice(&self.start.to_bytes());
        bytes[8..16].copy_from_slice(&self.end.to_bytes());

        bytes
    }

    /// Writes [`Segment`]s one after another, as an array of them holds them
    #[must_use]
    pub fn array_to_bytes(items: &[Self]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(items.len() * Self::SIZE);
        for item in items {
            bytes.extend_from_slice(&item.to_bytes());
        }

        bytes
    }
}

impl From<&Self> for Segment {
    fn from(value: &Self) -> Self {
        *value
    }
}

/// An array of [`Segment`]s, which reads each struct when it's asked for
#[derive(Clone, Copy, Debug)]
pub struct SegmentArray<'a> {
    structs: &'a [[u8; Segment::SIZE]],
}

impl<'a> SegmentArray<'a> {
    /// The number of structs
    pub const fn len(&self) -> usize {
        self.structs.len()
    }

    pub const fn is_empty(&self) -> bool {
        self.structs.is_empty()
    }

    /// Reads struct `index`, or returns `None` past the end
    pub fn get(&self, index: usize) -> Option<Segment> {
        self.structs.get(index).map(Segment::from_bytes)
    }

    /// Iterates over the structs
    pub fn iter(&self) -> impl ExactSizeIterator<Item = Segment> + use<'a> {
        self.structs.iter().map(Segment::from_bytes)
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Point {
    pub x: f32,
    pub y: f32,
}

impl Point {
    /// The byte length of a [`Point`]
    pub const SIZE: usize = 8;

    /// The alignment of an array of a [`Point`]: its largest scalar's size
    pub const ALIGNMENT: Alignment = Alignment::Four;

    /// Reads a [`Point`] from the start of `bytes`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if `bytes` are shorter than [`Self::SIZE`].
    pub fn read(bytes: &[u8]) -> Result<Self, DecodeError> {
        match bytes.first_chunk() {
            Some(bytes) => Ok(Self::from_bytes(bytes)),
            None => Err(DecodeError::OutOfRange {
                position: 0,
                byte_length: 8,
                available: bytes.len(),
            }),
        }
    }

    /// Reads a [`Point`] from its bytes, such as those of an array of them
    #[must_use]
    #[allow(clippy::trivially_copy_pass_by_ref)]
    pub fn from_bytes(bytes: &[u8; 8]) -> Self {
        Self {
            x: f32::from_le_bytes(bytes[0..4].try_into().unwrap_or_default()),
            y: f32::from_le_bytes(bytes[4..8].try_into().unwrap_or_default()),
        }
    }

    #[must_use]
    pub fn to_bytes(self) -> [u8; 8] {
        let mut bytes = [0; Self::SIZE];
        bytes[0..4].copy_from_slice(&self.x.to_le_bytes());
        bytes[4..8].copy_from_slice(&self.y.to_le_bytes());

        bytes
    }

    /// Writes [`Point`]s one after another, as an array of them holds them
    #[must_use]
    pub fn array_to_bytes(items: &[Self]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(items.len() * Self::SIZE);
        for item in items {
            bytes.extend_from_slice(&item.to_bytes());
        }

        bytes
    }
}

impl From<&Self> for Point {
    fn from(value: &Self) -> Self {
        *value
    }
}

/// An array of [`Point`]s, which reads each struct when it's asked for
#[derive(Clone, Copy, Debug)]
pub struct PointArray<'a> {
    structs: &'a [[u8; Point::SIZE]],
}

impl<'a> PointArray<'a> {
    /// The number of structs
    pub const fn len(&self) -> usize {
        self.structs.len()
    }

    pub const fn is_empty(&self) -> bool {
        self.structs.is_empty()
    }

    /// Reads struct `index`, or returns `None` past the end
    pub fn get(&self, index: usize) -> Option<Point> {
        self.structs.get(index).map(Point::from_bytes)
    }

    /// Iterates over the structs
    pub fn iter(&self) -> impl ExactSizeIterator<Item = Point> + use<'a> {
        self.structs.iter().map(Point::from_bytes)
    }
}

/// A struct of every scalar type and a bool, at fixed offsets without
/// padding
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Packed {
    pub int8: i8,
    pub uint8: u8,
    pub int16: i16,
    pub uint16: u16,
    pub int32: i32,
    pub uint32: u32,
    pub int64: i64,
    pub uint64: u64,
    pub float32: f32,
    pub float64: f64,
    pub bool: bool,
}

impl Packed {
    /// The byte length of a [`Packed`]
    pub const SIZE: usize = 43;

    /// The alignment of an array of a [`Packed`]: its largest scalar's size
    pub const ALIGNMENT: Alignment = Alignment::Eight;

    /// Reads a [`Packed`] from the start of `bytes`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if `bytes` are shorter than [`Self::SIZE`].
    pub fn read(bytes: &[u8]) -> Result<Self, DecodeError> {
        match bytes.first_chunk() {
            Some(bytes) => Ok(Self::from_bytes(bytes)),
            None => Err(DecodeError::OutOfRange {
                position: 0,
                byte_length: 43,
                available: bytes.len(),
            }),
        }
    }

    /// Reads a [`Packed`] from its bytes, such as those of an array of them
    #[must_use]
    pub fn from_bytes(bytes: &[u8; 43]) -> Self {
        Self {
            int8: i8::from_le_bytes(bytes[0..1].try_into().unwrap_or_default()),
            uint8: u8::from_le_bytes(bytes[1..2].try_into().unwrap_or_default()),
            int16: i16::from_le_bytes(bytes[2..4].try_into().unwrap_or_default()),
            uint16: u16::from_le_bytes(bytes[4..6].try_into().unwrap_or_default()),
            int32: i32::from_le_bytes(bytes[6..10].try_into().unwrap_or_default()),
            uint32: u32::from_le_bytes(bytes[10..14].try_into().unwrap_or_default()),
            int64: i64::from_le_bytes(bytes[14..22].try_into().unwrap_or_default()),
            uint64: u64::from_le_bytes(bytes[22..30].try_into().unwrap_or_default()),
            float32: f32::from_le_bytes(bytes[30..34].try_into().unwrap_or_default()),
            float64: f64::from_le_bytes(bytes[34..42].try_into().unwrap_or_default()),
            bool: bytes[42] != 0,
        }
    }

    #[must_use]
    pub fn to_bytes(self) -> [u8; 43] {
        let mut bytes = [0; Self::SIZE];
        bytes[0..1].copy_from_slice(&self.int8.to_le_bytes());
        bytes[1..2].copy_from_slice(&self.uint8.to_le_bytes());
        bytes[2..4].copy_from_slice(&self.int16.to_le_bytes());
        bytes[4..6].copy_from_slice(&self.uint16.to_le_bytes());
        bytes[6..10].copy_from_slice(&self.int32.to_le_bytes());
        bytes[10..14].copy_from_slice(&self.uint32.to_le_bytes());
        bytes[14..22].copy_from_slice(&self.int64.to_le_bytes());
        bytes[22..30].copy_from_slice(&self.uint64.to_le_bytes());
        bytes[30..34].copy_from_slice(&self.float32.to_le_bytes());
        bytes[34..42].copy_from_slice(&self.float64.to_le_bytes());
        bytes[42] = u8::from(self.bool);

        bytes
    }

    /// Writes [`Packed`]s one after another, as an array of them holds them
    #[must_use]
    pub fn array_to_bytes(items: &[Self]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(items.len() * Self::SIZE);
        for item in items {
            bytes.extend_from_slice(&item.to_bytes());
        }

        bytes
    }
}

/// Documentation of several lines.
///
/// It can hold Markdown's `code spans`, non-ASCII text such as å, 世界 and
/// 🦀, and text that closes a comment or string in some language: */, """,
/// a backslash \ and a trailing quote"
///
/// Javadoc and `JSDoc` read it as text, with HTML's <b>, &amp; and &,
/// Javadoc's {@link Object} and `{@code x}`, Java's Unicode escape \u000A,
/// and a tag at the start of a line:
/// @deprecated
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Documented {
    /// A field's documentation, of one line
    pub one: u8,
    /// A field's documentation,
    /// of two lines
    pub two: u16,
    pub undocumented: u32,
}

impl Documented {
    /// The byte length of a [`Documented`]
    pub const SIZE: usize = 7;

    /// The alignment of an array of a [`Documented`]: its largest scalar's size
    pub const ALIGNMENT: Alignment = Alignment::Four;

    /// Reads a [`Documented`] from the start of `bytes`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if `bytes` are shorter than [`Self::SIZE`].
    pub fn read(bytes: &[u8]) -> Result<Self, DecodeError> {
        match bytes.first_chunk() {
            Some(bytes) => Ok(Self::from_bytes(bytes)),
            None => Err(DecodeError::OutOfRange {
                position: 0,
                byte_length: 7,
                available: bytes.len(),
            }),
        }
    }

    /// Reads a [`Documented`] from its bytes, such as those of an array of them
    #[must_use]
    #[allow(clippy::trivially_copy_pass_by_ref)]
    pub fn from_bytes(bytes: &[u8; 7]) -> Self {
        Self {
            one: u8::from_le_bytes(bytes[0..1].try_into().unwrap_or_default()),
            two: u16::from_le_bytes(bytes[1..3].try_into().unwrap_or_default()),
            undocumented: u32::from_le_bytes(bytes[3..7].try_into().unwrap_or_default()),
        }
    }

    #[must_use]
    pub fn to_bytes(self) -> [u8; 7] {
        let mut bytes = [0; Self::SIZE];
        bytes[0..1].copy_from_slice(&self.one.to_le_bytes());
        bytes[1..3].copy_from_slice(&self.two.to_le_bytes());
        bytes[3..7].copy_from_slice(&self.undocumented.to_le_bytes());

        bytes
    }

    /// Writes [`Documented`]s one after another, as an array of them holds them
    #[must_use]
    pub fn array_to_bytes(items: &[Self]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(items.len() * Self::SIZE);
        for item in items {
            bytes.extend_from_slice(&item.to_bytes());
        }

        bytes
    }
}

impl From<&Self> for Documented {
    fn from(value: &Self) -> Self {
        *value
    }
}

/// An array of [`Documented`]s, which reads each struct when it's asked for
#[derive(Clone, Copy, Debug)]
pub struct DocumentedArray<'a> {
    structs: &'a [[u8; Documented::SIZE]],
}

impl<'a> DocumentedArray<'a> {
    /// The number of structs
    pub const fn len(&self) -> usize {
        self.structs.len()
    }

    pub const fn is_empty(&self) -> bool {
        self.structs.is_empty()
    }

    /// Reads struct `index`, or returns `None` past the end
    pub fn get(&self, index: usize) -> Option<Documented> {
        self.structs.get(index).map(Documented::from_bytes)
    }

    /// Iterates over the structs
    pub fn iter(&self) -> impl ExactSizeIterator<Item = Documented> + use<'a> {
        self.structs.iter().map(Documented::from_bytes)
    }
}

/// Enums as fields and in arrays, which are stored as their integer types
#[derive(Clone, Copy, Debug)]
pub struct Enums<'a> {
    bytes: &'a [u8],
}

impl<'a> Enums<'a> {
    const LAYOUT: TableLayout = TableLayout::DEFAULT;

    /// Reads an [`Enums`] from `bytes`
    pub const fn new(bytes: &'a [u8]) -> Self {
        Self { bytes }
    }

    /// An enum of one byte
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn level(&self) -> Result<Level, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(0)?;
        reader.get_u8(position).map(Level)
    }

    /// An array of enums, which is an array of their integer type
    ///
    /// Each element is the `u8` of a [`Level`]
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn levels(&self) -> Result<&'a [u8], DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(1)?;
        reader.get_u8_array(position)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn direction(&self) -> Result<Direction, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(2)?;
        reader.get_i8(position).map(Direction)
    }

    /// Each element is the `i8` of a [`Direction`]
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn directions(&self) -> Result<ArrayView<'a, i8>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(3)?;
        reader.get_i8_array(position)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn unit(&self) -> Result<Unit, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(4)?;
        reader.get_u16(position).map(Unit)
    }

    /// Each element is the `u16` of a [`Unit`]
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn units(&self) -> Result<ArrayView<'a, u16>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(5)?;
        reader.get_u16_array(position)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn change(&self) -> Result<Change, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(6)?;
        reader.get_i16(position).map(Change)
    }

    /// Each element is the `i16` of a [`Change`]
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn changes(&self) -> Result<ArrayView<'a, i16>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(7)?;
        reader.get_i16_array(position)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn status(&self) -> Result<Status, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(8)?;
        reader.get_u32(position).map(Status)
    }

    /// Each element is the `u32` of a [`Status`]
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn statuses(&self) -> Result<ArrayView<'a, u32>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(9)?;
        reader.get_u32_array(position)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn sign(&self) -> Result<Sign, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(10)?;
        reader.get_i32(position).map(Sign)
    }

    /// Each element is the `i32` of a [`Sign`]
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn signs(&self) -> Result<ArrayView<'a, i32>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(11)?;
        reader.get_i32_array(position)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn mask(&self) -> Result<Mask, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(12)?;
        reader.get_u64(position).map(Mask)
    }

    /// Each element is the `u64` of a [`Mask`]
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn masks(&self) -> Result<ArrayView<'a, u64>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(13)?;
        reader.get_u64_array(position)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn extent(&self) -> Result<Extent, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(14)?;
        reader.get_i64(position).map(Extent)
    }

    /// Each element is the `i64` of an [`Extent`]
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn extents(&self) -> Result<ArrayView<'a, i64>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(15)?;
        reader.get_i64_array(position)
    }

    /// An enum whose values are keywords
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn word(&self) -> Result<Word, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(16)?;
        reader.get_u8(position).map(Word)
    }

    /// A struct of enums
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn mark(&self) -> Result<Mark, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(17)?;
        let bytes = reader.get_struct(position, Mark::SIZE)?;

        Mark::read(bytes)
    }

    /// A view of the structs, which reads each [`Mark`] when it's asked for
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field or its structs lie outside the bytes.
    pub fn marks(&self) -> Result<MarkArray<'a>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(18)?;
        let bytes = reader.get_struct_array(position, Mark::SIZE)?;
        let (structs, _) = bytes.as_chunks::<{ Mark::SIZE }>();

        Ok(MarkArray { structs })
    }

    /// Tables of an enum, which a vector's view reads
    ///
    /// A view of the items, which reads each [`Step`] when it's asked for, and
    /// fails then if its bytes are corrupt
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field, or the vector's count or the ends of its items, lie outside the bytes.
    pub fn steps(&self) -> Result<StepVector<'a>, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(19)?;
        Ok(StepVector {
            vector: reader.get_vector(position)?,
        })
    }
}

/// The fields of an [`Enums`], to write
#[derive(Clone, Debug)]
pub struct EnumsFields<'a, T = Mark, U = StepFields<'a>> {
    /// An enum of one byte
    pub level: Level,
    /// An array of enums, which is an array of their integer type
    ///
    /// Each element is the `u8` of a [`Level`]
    pub levels: &'a [u8],
    pub direction: Direction,
    /// Each element is the `i8` of a [`Direction`]
    pub directions: &'a [i8],
    pub unit: Unit,
    /// Each element is the `u16` of a [`Unit`]
    pub units: &'a [u16],
    pub change: Change,
    /// Each element is the `i16` of a [`Change`]
    pub changes: &'a [i16],
    pub status: Status,
    /// Each element is the `u32` of a [`Status`]
    pub statuses: &'a [u32],
    pub sign: Sign,
    /// Each element is the `i32` of a [`Sign`]
    pub signs: &'a [i32],
    pub mask: Mask,
    /// Each element is the `u64` of a [`Mask`]
    pub masks: &'a [u64],
    pub extent: Extent,
    /// Each element is the `i64` of an [`Extent`]
    pub extents: &'a [i64],
    /// An enum whose values are keywords
    pub word: Word,
    /// A struct of enums
    pub mark: Mark,
    /// [`Mark`]s, or items of any type `T` whose reference converts into a [`Mark`]
    pub marks: &'a [T],
    /// Tables of an enum, which a vector's view reads
    ///
    /// [`StepFields`], or items of any type `U` whose reference converts into them
    pub steps: &'a [U],
}

impl<'a, T, U> EnumsFields<'a, T, U>
where
    &'a T: Into<Mark>,
    &'a U: Into<StepFields<'a>>,
{
    /// Writes an [`Enums`] with every field
    ///
    /// # Errors
    ///
    /// Returns a [`BuildError`] if it's longer than its offset type, `uint32`, addresses.
    pub fn serialize(&self) -> Result<Vec<u8>, BuildError> {
        let mut sizer = TableSizer::new(20, Enums::LAYOUT)?;
        sizer.add_u8();
        sizer.add_u8_array(self.levels.len());
        sizer.add_i8();
        sizer.add_i8_array(self.directions.len());
        sizer.add_u16();
        sizer.add_u16_array(self.units.len());
        sizer.add_i16();
        sizer.add_i16_array(self.changes.len());
        sizer.add_u32();
        sizer.add_u32_array(self.statuses.len());
        sizer.add_i32();
        sizer.add_i32_array(self.signs.len());
        sizer.add_u64();
        sizer.add_u64_array(self.masks.len());
        sizer.add_i64();
        sizer.add_i64_array(self.extents.len());
        sizer.add_u8();
        sizer.add_struct(Mark::SIZE);
        sizer.add_struct_array(self.marks.len(), Mark::SIZE, Mark::ALIGNMENT);
        sizer.add_vector(self.steps.len());
        for item in self.steps {
            let fields: StepFields<'a> = item.into();
            fields.size(&mut sizer);
        }

        let mut writer = sizer.writer()?;
        writer.set_u8(0, self.level.0);
        writer.set_u8_array(1, self.levels);
        writer.set_i8(2, self.direction.0);
        writer.set_i8_array(3, self.directions);
        writer.set_u16(4, self.unit.0);
        writer.set_u16_array(5, self.units);
        writer.set_i16(6, self.change.0);
        writer.set_i16_array(7, self.changes);
        writer.set_u32(8, self.status.0);
        writer.set_u32_array(9, self.statuses);
        writer.set_i32(10, self.sign.0);
        writer.set_i32_array(11, self.signs);
        writer.set_u64(12, self.mask.0);
        writer.set_u64_array(13, self.masks);
        writer.set_i64(14, self.extent.0);
        writer.set_i64_array(15, self.extents);
        writer.set_u8(16, self.word.0);
        writer.set_struct(17, &self.mark.to_bytes());
        writer.set_structs(
            18,
            self.marks,
            |item| Mark::to_bytes(item.into()),
            Mark::ALIGNMENT,
        );
        let vector = writer.set_vector(19, self.steps.len());
        for (index, item) in self.steps.iter().enumerate() {
            let fields: StepFields<'a> = item.into();
            fields.write(&mut writer);
            writer.set_item_end(vector, index);
        }

        writer.into_bytes()
    }
}

/// A table of an enum, a struct of enums and a string
#[derive(Clone, Copy, Debug)]
pub struct Step<'a> {
    bytes: &'a [u8],
    position: usize,
}

impl<'a> Step<'a> {
    /// Reads the table at `position` in `bytes`, as its parent's getter finds it
    const fn new(bytes: &'a [u8], position: usize) -> Self {
        Self { bytes, position }
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn level(&self) -> Result<Level, DecodeError> {
        let reader = TableReader::new(self.bytes, TableLayout::DEFAULT);
        let position = reader.field_offset(self.position, 0)?;
        reader.get_u8(position).map(Level)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn mark(&self) -> Result<Mark, DecodeError> {
        let reader = TableReader::new(self.bytes, TableLayout::DEFAULT);
        let position = reader.field_offset(self.position, 1)?;
        let bytes = reader.get_struct(position, Mark::SIZE)?;

        Mark::read(bytes)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn name(&self) -> Result<&'a str, DecodeError> {
        let reader = TableReader::new(self.bytes, TableLayout::DEFAULT);
        let position = reader.field_offset(self.position, 2)?;
        reader.get_str(position)
    }
}

/// The fields of a [`Step`], to write
#[derive(Clone, Debug)]
pub struct StepFields<'a> {
    pub level: Level,
    pub mark: Mark,
    pub name: &'a str,
}

impl StepFields<'_> {
    /// The alignment that a parent pads a [`Step`] to: the largest alignment of its
    /// arrays and nested tables, or 1
    pub const ALIGNMENT: Alignment = Alignment::One;

    /// Adds a [`Step`] to its parent's sizer, after the field or vector that holds it
    pub fn size(&self, sizer: &mut TableSizer) {
        let parent = sizer.start_table(3);
        sizer.add_u8();
        sizer.add_struct(Mark::SIZE);
        sizer.add_str(self.name);
        sizer.end_table(parent);
    }

    /// Writes a [`Step`] where its parent's writer is, after the field or vector that holds it
    pub fn write(&self, writer: &mut TableWriter) {
        let parent = writer.start_table(3);
        writer.set_u8(0, self.level.0);
        writer.set_struct(1, &self.mark.to_bytes());
        writer.set_str(2, self.name);
        writer.end_table(parent);
    }
}

impl From<&Self> for StepFields<'_> {
    fn from(value: &Self) -> Self {
        value.clone()
    }
}

/// A vector of [`Step`]s, which reads each item when it's asked for
#[derive(Clone, Copy, Debug)]
pub struct StepVector<'a> {
    vector: Vector<'a>,
}

impl<'a> StepVector<'a> {
    /// The number of items
    pub const fn len(&self) -> usize {
        self.vector.len()
    }

    pub const fn is_empty(&self) -> bool {
        self.vector.is_empty()
    }

    /// Reads item `index`, without reading the others, or returns `None` past the end
    ///
    /// # Errors
    ///
    /// Returns `Some` of a [`DecodeError`] if the item lies outside the bytes.
    pub fn get(&self, index: usize) -> Option<Result<Step<'a>, DecodeError>> {
        self.vector.get_in_place(index).map(Self::item)
    }

    /// Iterates over the items, reading each item's end once
    pub fn iter(&self) -> impl ExactSizeIterator<Item = Result<Step<'a>, DecodeError>> + use<'a> {
        self.vector.iter_in_place().map(Self::item)
    }

    /// Reads an item in place, from its bytes and those after it in the message
    fn item(bytes: Result<&'a [u8], DecodeError>) -> Result<Step<'a>, DecodeError> {
        Ok(Step::new(bytes?, 0))
    }
}

/// A struct of enums of 1, 2 and 8 bytes beside a scalar, and of a struct
/// that holds an enum
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Mark {
    pub level: Level,
    pub change: Change,
    pub weight: f32,
    pub extent: Extent,
    pub turn: Turn,
}

impl Mark {
    /// The byte length of a [`Mark`]
    pub const SIZE: usize = 24;

    /// The alignment of an array of a [`Mark`]: its largest scalar's size
    pub const ALIGNMENT: Alignment = Alignment::Eight;

    /// Reads a [`Mark`] from the start of `bytes`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if `bytes` are shorter than [`Self::SIZE`].
    pub fn read(bytes: &[u8]) -> Result<Self, DecodeError> {
        match bytes.first_chunk() {
            Some(bytes) => Ok(Self::from_bytes(bytes)),
            None => Err(DecodeError::OutOfRange {
                position: 0,
                byte_length: 24,
                available: bytes.len(),
            }),
        }
    }

    /// Reads a [`Mark`] from its bytes, such as those of an array of them
    #[must_use]
    pub fn from_bytes(bytes: &[u8; 24]) -> Self {
        Self {
            level: Level(u8::from_le_bytes(
                bytes[0..1].try_into().unwrap_or_default(),
            )),
            change: Change(i16::from_le_bytes(
                bytes[1..3].try_into().unwrap_or_default(),
            )),
            weight: f32::from_le_bytes(bytes[3..7].try_into().unwrap_or_default()),
            extent: Extent(i64::from_le_bytes(
                bytes[7..15].try_into().unwrap_or_default(),
            )),
            turn: Turn {
                direction: Direction(i8::from_le_bytes(
                    bytes[15..16].try_into().unwrap_or_default(),
                )),
                mask: Mask(u64::from_le_bytes(
                    bytes[16..24].try_into().unwrap_or_default(),
                )),
            },
        }
    }

    #[must_use]
    pub fn to_bytes(self) -> [u8; 24] {
        let mut bytes = [0; Self::SIZE];
        bytes[0..1].copy_from_slice(&self.level.0.to_le_bytes());
        bytes[1..3].copy_from_slice(&self.change.0.to_le_bytes());
        bytes[3..7].copy_from_slice(&self.weight.to_le_bytes());
        bytes[7..15].copy_from_slice(&self.extent.0.to_le_bytes());
        bytes[15..24].copy_from_slice(&self.turn.to_bytes());

        bytes
    }

    /// Writes [`Mark`]s one after another, as an array of them holds them
    #[must_use]
    pub fn array_to_bytes(items: &[Self]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(items.len() * Self::SIZE);
        for item in items {
            bytes.extend_from_slice(&item.to_bytes());
        }

        bytes
    }
}

impl From<&Self> for Mark {
    fn from(value: &Self) -> Self {
        *value
    }
}

/// An array of [`Mark`]s, which reads each struct when it's asked for
#[derive(Clone, Copy, Debug)]
pub struct MarkArray<'a> {
    structs: &'a [[u8; Mark::SIZE]],
}

impl<'a> MarkArray<'a> {
    /// The number of structs
    pub const fn len(&self) -> usize {
        self.structs.len()
    }

    pub const fn is_empty(&self) -> bool {
        self.structs.is_empty()
    }

    /// Reads struct `index`, or returns `None` past the end
    pub fn get(&self, index: usize) -> Option<Mark> {
        self.structs.get(index).map(Mark::from_bytes)
    }

    /// Iterates over the structs
    pub fn iter(&self) -> impl ExactSizeIterator<Item = Mark> + use<'a> {
        self.structs.iter().map(Mark::from_bytes)
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Turn {
    pub direction: Direction,
    pub mask: Mask,
}

impl Turn {
    /// The byte length of a [`Turn`]
    pub const SIZE: usize = 9;

    /// The alignment of an array of a [`Turn`]: its largest scalar's size
    pub const ALIGNMENT: Alignment = Alignment::Eight;

    /// Reads a [`Turn`] from the start of `bytes`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if `bytes` are shorter than [`Self::SIZE`].
    pub fn read(bytes: &[u8]) -> Result<Self, DecodeError> {
        match bytes.first_chunk() {
            Some(bytes) => Ok(Self::from_bytes(bytes)),
            None => Err(DecodeError::OutOfRange {
                position: 0,
                byte_length: 9,
                available: bytes.len(),
            }),
        }
    }

    /// Reads a [`Turn`] from its bytes, such as those of an array of them
    #[must_use]
    pub fn from_bytes(bytes: &[u8; 9]) -> Self {
        Self {
            direction: Direction(i8::from_le_bytes(
                bytes[0..1].try_into().unwrap_or_default(),
            )),
            mask: Mask(u64::from_le_bytes(
                bytes[1..9].try_into().unwrap_or_default(),
            )),
        }
    }

    #[must_use]
    pub fn to_bytes(self) -> [u8; 9] {
        let mut bytes = [0; Self::SIZE];
        bytes[0..1].copy_from_slice(&self.direction.0.to_le_bytes());
        bytes[1..9].copy_from_slice(&self.mask.0.to_le_bytes());

        bytes
    }

    /// Writes [`Turn`]s one after another, as an array of them holds them
    #[must_use]
    pub fn array_to_bytes(items: &[Self]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(items.len() * Self::SIZE);
        for item in items {
            bytes.extend_from_slice(&item.to_bytes());
        }

        bytes
    }
}
